@startuml

class Bus {
  + LicensePlateNumber : string
  + InRepairShop : boolean
}

class Driver {
  + ID : int
  + Name : string
  + OnSickLeave : boolean
}

class Route {
  + Number : int
  + MorningShifts : Shift[]
  + AfternoonShifts : Shift[]
  + NightShifts : Shift[]
}

class Shift {
  + Bus : Bus
  + Driver : Driver
  + Date : date
}

Bus "1" -- "*" Route
Driver "0..*" -- "*" Shift

@enduml

